import{_ as a,o as e,c as r,ae as o}from"./chunks/framework.BX6FPmO9.js";const m=JSON.parse('{"title":"資料治理與前端對等","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/data-governance.md","filePath":"architecture/data-governance.md"}'),n={name:"architecture/data-governance.md"};function d(s,t,c,l,i,h){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="資料治理與前端對等" tabindex="-1">資料治理與前端對等 <a class="header-anchor" href="#資料治理與前端對等" aria-label="Permalink to &quot;資料治理與前端對等&quot;">​</a></h1><p><strong>類型</strong>：reference | <strong>權重</strong>：2</p><p>本文件說明：為何前端不追求「資料格式效率」（如 Delta/Parquet），而追求<strong>可治理的資料層</strong>；以及如何把「資料治理」精神落實在契約、mock 與版本化上。</p><hr><h2 id="一、delta-parquet-的啟發-不是直接拿來用" tabindex="-1">一、Delta/Parquet 的啟發（不是直接拿來用） <a class="header-anchor" href="#一、delta-parquet-的啟發-不是直接拿來用" aria-label="Permalink to &quot;一、Delta/Parquet 的啟發（不是直接拿來用）&quot;">​</a></h2><p>Delta/Parquet 的核心價值是：把<strong>檔案型資料湖</strong>變成<strong>可治理的表格層</strong>——版本、交易紀錄、併發寫入、回溯與一致性。常用在 analytics / lakehouse / ETL，<strong>不是</strong>為前端即時串接效能而設計。</p><p>對前端而言，要加速的是<strong>協作效率</strong>，不是「資料是不是 Parquet」；瓶頸通常是：</p><ul><li>API contract 不穩（schema 常變、欄位語意不清）</li><li>mock 與真實環境漂移</li><li>重複打 API、快取策略混亂</li><li>UI state 與 server state 混在一起、難測</li></ul><p><strong>啟發點</strong>：把「資料治理」變成<strong>制度</strong>（log、版本、schema enforcement），並在前端用對等的做法落地。</p><hr><h2 id="二、前端可落地的對等物-contract-first-可執行的-mock" tabindex="-1">二、前端可落地的對等物：Contract-first + 可執行的 mock <a class="header-anchor" href="#二、前端可落地的對等物-contract-first-可執行的-mock" aria-label="Permalink to &quot;二、前端可落地的對等物：Contract-first + 可執行的 mock&quot;">​</a></h2><table tabindex="0"><thead><tr><th>做法</th><th>本專案對應</th></tr></thead><tbody><tr><td>單一資料契約來源</td><td>Zod schema（<code>app/shared/contracts/</code>）；未來可接 OpenAPI / GraphQL schema / JSON Schema</td></tr><tr><td>由契約生成型別與 client</td><td>目前型別由 <code>z.infer</code>；未來可 codegen client</td></tr><tr><td>MSW handler 由契約驅動</td><td>Handler 回傳前必須通過 schema parse（見 <code>app/test/handlers.ts</code>）</td></tr><tr><td>CI 強制</td><td>所有 API 須走約定路徑；每個 API 須有 handler；handler response 須通過 schema parse（<code>lint:handlers</code>）</td></tr></tbody></table><p>效果：減少「用猜的、等後端、口頭同步」，直接提升<strong>串接與協作效率</strong>。</p><hr><h2 id="三、兩種「高效」-效能-vs-開發速度" tabindex="-1">三、兩種「高效」：效能 vs 開發速度 <a class="header-anchor" href="#三、兩種「高效」-效能-vs-開發速度" aria-label="Permalink to &quot;三、兩種「高效」：效能 vs 開發速度&quot;">​</a></h2><h3 id="a-效能-runtime" tabindex="-1">A. 效能（runtime） <a class="header-anchor" href="#a-效能-runtime" aria-label="Permalink to &quot;A. 效能（runtime）&quot;">​</a></h3><ul><li><strong>Server state 為主</strong>：可引入 TanStack Query / SWR（dedupe、cache、stale-while-revalidate、retry、pagination）。</li><li><strong>快取 key 與 invalidation</strong> 比「少打 API」更重要。</li><li><strong>BFF 或 edge aggregation</strong>：多個後端呼叫聚合成前端友善的 API，減少 chatty network。</li></ul><h3 id="b-開發速度-協作生產力" tabindex="-1">B. 開發速度（協作生產力） <a class="header-anchor" href="#b-開發速度-協作生產力" aria-label="Permalink to &quot;B. 開發速度（協作生產力）&quot;">​</a></h3><ul><li><strong>Contract-first + codegen</strong>：減少手寫與錯誤（本專案先做 Zod + 手寫型別，未來可接 OpenAPI codegen）。</li><li><strong>MSW 即規格</strong>：所有人有相同、可重現的 mock 資料。</li><li><strong>測試導向的資料層</strong>：handler test / contract test 先於 UI。</li></ul><p>建議順序：<strong>先建 contract + service layer + CI</strong>（已做），再視需求導入 query caching 或 BFF。</p><hr><h2 id="四、mock-dataset-版本化-delta-版本精神的對等" tabindex="-1">四、Mock Dataset 版本化（Delta 版本精神的對等） <a class="header-anchor" href="#四、mock-dataset-版本化-delta-版本精神的對等" aria-label="Permalink to &quot;四、Mock Dataset 版本化（Delta 版本精神的對等）&quot;">​</a></h2><p>與 Delta time travel 對齊：<strong>可回溯、可重現、可控變更</strong>。</p><ul><li><strong>Mock scenario 以 dataset version 管理</strong>：例如 <code>app/test/datasets/v1/</code>、<code>app/test/datasets/v2/</code>。</li><li><strong>Schema 變更</strong>：不直接改掉舊 dataset，而是<strong>新增版本</strong>並在該版目錄提供 <code>MIGRATION.md</code> 或 changelog。</li><li><strong>測試可指定 dataset version</strong>：環境變數或 test 設定指定用 v1 或 v2，結果可重現。</li><li>見 <a href="./../conventions/mock-dataset-versioning.html">mock-dataset-versioning</a> 與 <a href="./../product/mock-data.html">mock-data</a>。</li></ul><hr><h2 id="五、現況與落地清單" tabindex="-1">五、現況與落地清單 <a class="header-anchor" href="#五、現況與落地清單" aria-label="Permalink to &quot;五、現況與落地清單&quot;">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>現況</th><th>建議下一步</th></tr></thead><tbody><tr><td>資料來源</td><td>REST（Remix resource routes）</td><td>維持；若後端有 OpenAPI 可考慮 codegen</td></tr><tr><td>OpenAPI</td><td>無</td><td>可選：由 Zod 產 JSON Schema 或由 OpenAPI 產 Zod</td></tr><tr><td>前端資料取得</td><td>Remix <code>useFetcher</code> / loader</td><td>契約 + handler + CI 已就緒；可選加 TanStack Query 做 cache</td></tr><tr><td>Contract</td><td>Zod（<code>app/shared/contracts/</code>）</td><td>維持單一來源；handler/route 皆 parse</td></tr><tr><td>Mock</td><td>MSW handler，response 經 schema</td><td>補 Mock Dataset 版本化（datasets/v1, v2）</td></tr><tr><td>CI</td><td>lint:handlers、schema 於 handler 內 parse</td><td>可選：contract test 對 staging、dataset version 檢查</td></tr></tbody></table><p><strong>優先優化目標</strong>：本專案已選 <strong>(1) 多人協作下的串接速度與穩定性</strong>（contract + MSW + CI）。若之後要同時優化 <strong>(2) 頁面效能與網路效率</strong>，順序為：先鞏固 contract + service layer，再導入 TanStack Query / BFF。</p><hr><h2 id="六、相關文件" tabindex="-1">六、相關文件 <a class="header-anchor" href="#六、相關文件" aria-label="Permalink to &quot;六、相關文件&quot;">​</a></h2><ul><li><a href="./../conventions/data-test-driven.html">data-test-driven</a>：Spec → Contract → Mock → Test → UI、強制規則</li><li><a href="./../../specs/api/contract-schema.html">contract-schema</a>：Zod 契約與 template</li><li><a href="./../../specs/api/handler-mapping.html">handler-mapping</a>：API 與 handler 對應</li><li><a href="./../conventions/mock-dataset-versioning.html">mock-dataset-versioning</a>：dataset 目錄、版本、migration</li><li><a href="./../product/mock-data.html">mock-data</a>：種子、MSW、最小維護原則</li></ul>',31)])])}const p=a(n,[["render",d]]);export{m as __pageData,p as default};
